const abs = (p) => new URL(p, self.registration.scope).href;

self.addEventListener('install', (e) => {
  e.waitUntil((async () => {
    const c = await caches.open(STATIC_CACHE);
    await c.addAll(STATIC.map((u) => new Request(abs(u), { cache: 'reload' })));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('uw-static-') && k !== STATIC_CACHE).map((k) => caches.delete(k)));
    const ac = await caches.open(AUDIO_CACHE);
    const wanted = new Set(AUDIO.map(abs));
    for (const req of await ac.keys()) if (!wanted.has(req.url)) await ac.delete(req);
    await self.clients.claim();
  })());
});

async function broadcast(msg) {
  const cs = await self.clients.matchAll({ includeUncontrolled: true });
  cs.forEach((c) => c.postMessage(msg));
}

async function audioStatus() {
  const ac = await caches.open(AUDIO_CACHE);
  const have = new Set((await ac.keys()).map((r) => r.url));
  const urls = AUDIO.map(abs);
  return { type: 'status', version: VERSION, total: urls.length, done: urls.filter((u) => have.has(u)).length };
}

let running = null;
async function precacheAudio() {
  const ac = await caches.open(AUDIO_CACHE);
  const have = new Set((await ac.keys()).map((r) => r.url));
  const urls = AUDIO.map(abs);
  const todo = urls.filter((u) => !have.has(u));
  let done = urls.length - todo.length;
  let failed = 0;
  await broadcast({ type: 'progress', done, total: urls.length });
  let i = 0;
  async function worker() {
    while (i < todo.length) {
      const u = todo[i++];
      try {
        const r = await fetch(u, { cache: 'no-cache' });
        if (r.ok) await ac.put(u, r); else failed++;
      } catch (err) { failed++; }
      done++;
      if (done % 15 === 0) await broadcast({ type: 'progress', done, total: urls.length });
    }
  }
  await Promise.all(Array.from({ length: 6 }, worker));
  const st = await audioStatus();
  await broadcast({ type: 'progress', done: st.done, total: st.total, complete: true, failed });
}

self.addEventListener('message', (e) => {
  if (e.data === 'precache-audio') {
    if (!running) running = precacheAudio().finally(() => { running = null; });
    e.waitUntil(running);
  } else if (e.data === 'status') {
    e.waitUntil(audioStatus().then((s) => e.source && e.source.postMessage(s)));
  }
});

async function serveAudio(req) {
  const ac = await caches.open(AUDIO_CACHE);
  let res = await ac.match(req.url, { ignoreSearch: true });
  if (!res) {
    try {
      res = await fetch(req.url);
      if (res.ok) await ac.put(req.url, res.clone());
    } catch (err) {
      return new Response('', { status: 504 });
    }
  }
  const range = req.headers.get('range');
  if (!range) return res;
  // Safari needs proper 206 responses for media served from a service worker
  const buf = await res.arrayBuffer();
  const size = buf.byteLength;
  const m = /bytes=(\d*)-(\d*)/.exec(range) || [];
  let start = m[1] ? parseInt(m[1], 10) : 0;
  let end = m[2] ? parseInt(m[2], 10) : size - 1;
  if (!m[1] && m[2]) { start = Math.max(0, size - parseInt(m[2], 10)); end = size - 1; }
  end = Math.min(end, size - 1);
  if (start > end) return new Response('', { status: 416, headers: { 'Content-Range': `bytes */${size}` } });
  return new Response(buf.slice(start, end + 1), {
    status: 206,
    headers: {
      'Content-Type': 'audio/mpeg',
      'Content-Range': `bytes ${start}-${end}/${size}`,
      'Content-Length': String(end - start + 1),
      'Accept-Ranges': 'bytes',
    },
  });
}

self.addEventListener('fetch', (e) => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  if (url.pathname.includes('/audio/')) { e.respondWith(serveAudio(req)); return; }
  e.respondWith((async () => {
    const c = await caches.open(STATIC_CACHE);
    const hit = await c.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch (err) {
      if (req.mode === 'navigate') {
        const idx = await c.match(abs('index.html'));
        if (idx) return idx;
      }
      return new Response('Offline', { status: 503 });
    }
  })());
});
